import{_ as e,c as o,o as a,ag as i}from"./chunks/framework.DPDPlp3K.js";const h=JSON.parse('{"title":"Documentation","description":"","frontmatter":{"title":"Documentation"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),s={name:"index.md"};function r(n,t,c,l,u,d){return a(),o("div",null,t[0]||(t[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Welcome to the <strong>WooCommerce Attribute Stock</strong> online documentation.</p><p>With attribute stock, you can set up complex stock configurations in WooCommerce with relative ease. Track and manage shared stock, variable quantities, product addons, combo packs, measurements, components, and much more!</p><h2 id="what-problem-does-attribute-stock-solve" tabindex="-1">What problem does Attribute Stock solve? <a class="header-anchor" href="#what-problem-does-attribute-stock-solve" aria-label="Permalink to &quot;What problem does Attribute Stock solve?&quot;">​</a></h2><p>If you&#39;ve used WooCommerce for a little while, you know its stock capabilities are quite limited. Each product or product variation can have a stock quantity and that&#39;s about it. Essentially your products are your stock items.</p><p>This works fine when you&#39;re selling simple products, but as soon as you need to do things like share stock between multiple products, or deduct different amounts of stock quantities per sale, you&#39;re out of luck.</p><h2 id="how-does-attribute-stock-solve-this" tabindex="-1">How does Attribute Stock solve this? <a class="header-anchor" href="#how-does-attribute-stock-solve-this" aria-label="Permalink to &quot;How does Attribute Stock solve this?&quot;">​</a></h2><p>Attribute Stock extends WooCommerce&#39;s stock functionality by adding a few essential features like <a href="./attribute-stock">rule-based stock items</a> that can be easily shared between multiple products. And versatile <a href="./stock-multipliers">stock multipliers</a> to control the amount of stock deducted for each purchase of a product, variation, attribute term, or stock item.</p><p>Whether you make use of powerful rule-based stock items, or simply add stock multipliers to your products, your stock levels will be accurately tracked, product availability will be appropriately displayed, and over-purchasing will be prevented.</p><h2 id="design-principle" tabindex="-1">Design principle <a class="header-anchor" href="#design-principle" aria-label="Permalink to &quot;Design principle&quot;">​</a></h2><p>A primary design principle of Attribute Stock is to extend WooCommerce <em>without</em> changing its core functionality. In a nutshell this means plugins, themes and custom code that work with WooCommerce should also work seamlessly with Attribute Stock without any further modification.</p><p>While we do our best to ensure this, there are a few caveats which we&#39;ll touch on later in this documentation.</p>',12)]))}const m=e(s,[["render",r]]);export{h as __pageData,m as default};
